const config = $('Leer configuración de indexación').first().json.data;
const courses = $('Leer catálogo PostgreSQL').first().json.data?.items;
if (!Array.isArray(courses)) throw new Error('Respuesta del catálogo inválida');
if (courses.length === 0) return [];
return [{ json: { ...config, courses, inputs: courses.map(c => `Curso: ${c.name}\nDescripción: ${c.description}\nCategoría: ${c.category}\nNivel: ${c.level}\nDuración: ${c.durationHours} horas`) } }];

const cfg = $('Preparar textos de cursos').first().json;
const result = $input.first().json;
const vectors = result.data ?? result.body?.data;
if (!Array.isArray(vectors) || vectors.length !== cfg.courses.length) throw new Error('OpenRouter devolvió una cantidad de embeddings inválida');
const ordered = [...vectors].sort((a, b) => a.index - b.index);
const dimension = ordered[0]?.embedding?.length;
if (!Number.isInteger(dimension) || dimension < 1) throw new Error('Dimensión de embedding inválida');
for (const vector of ordered) if (vector.embedding.length !== dimension || vector.embedding.some(n => !Number.isFinite(n))) throw new Error('Los embeddings no tienen dimensión o valores válidos');
const points = cfg.courses.map((course, i) => ({ id: course.id, vector: ordered[i].embedding, payload: { course_id: course.id, name: course.name, description: course.description, category: course.category, level: course.level, duration_hours: course.durationHours, is_active: true } }));
return [{ json: { qdrantUrl: cfg.qdrantUrl.replace(/\/$/, ''), collection: cfg.collection, dimension, points } }];
